        { "id": "net_15", "title": "15. 我们上网聊天吧 | Let's chat online", "isFree": false, "audioKey": "180", "sentence": "我们上网聊天吧。", "pinyin": "Wǒmen shàngwǎng liáotiān ba.", "translation": "Let's chat online.", "note": "“聊天”= chat. “吧”= suggestion. This is a friendly way to invite someone to talk online.", "reply": "好啊，用哪个App？", "replyPinyin": "hǎo a， yòng nǎ gè A p p？", "vocabList": [{"word":"聊天","pinyin":"liáotiān","translation":"to chat","hskLevel":2}] }
