      "intro": "Share how you feel and comfort others — happy, tired, worried, angry, sad — in simple Chinese.",
      "introZh": "说说自己的心情，也学会安慰别人。",
      "cards": [
        { "id": "mood_01", "title": "01. 我今天很高兴 | I'm very happy today", "isFree": true, "audioKey": "226", "sentence": "我今天很高兴。", "pinyin": "Wǒ jīntiān hěn gāoxìng.", "translation": "I'm very happy today.", "note": "“高兴” is the most common word for happy. Use it for good news, meeting someone, or a good day.", "reply": "太好了！", "replyPinyin": "tài hǎo le！", "vocabList": [{"word":"高兴","pinyin":"gāoxìng","translation":"happy","hskLevel":1}] },
        { "id": "mood_02", "title": "02. 你看起来很快乐 | You look very happy", "isFree": true, "audioKey": "227", "sentence": "你看起来很快乐。", "pinyin": "Nǐ kàn qǐlái hěn kuàilè.", "translation": "You look very happy.", "note": "“看起来” means “looks like / seems.” “快乐” is similar to “高兴” but a bit more general, like “joyful.”", "reply": "谢谢，我今天很好。", "replyPinyin": "xiè xiè， wǒ jīn tiān hěn hǎo。", "vocabList": [{"word":"快乐","pinyin":"kuàilè","translation":"joyful","hskLevel":2}] },
        { "id": "mood_03", "title": "03. 我有点累 | I'm a little tired", "isFree": true, "audioKey": "228", "sentence": "我有点累。", "pinyin": "Wǒ yǒudiǎn lèi.", "translation": "I'm a little tired.", "note": "“有点” = a little. “累” = tired. This is a soft way to say you're tired, not complaining too much.", "reply": "那你休息一下。", "replyPinyin": "nà nǐ xiū xī yī xià。", "vocabList": [{"word":"累","pinyin":"lèi","translation":"tired","hskLevel":1}] },
        { "id": "mood_04", "title": "04. 我生气了 | I'm angry", "isFree": true, "audioKey": "229", "sentence": "我生气了。", "pinyin": "Wǒ shēngqì le.", "translation": "I'm angry.", "note": "“生气” = angry. The “了” shows a change — you weren't angry before, but now you are. Use it carefully; it's direct.", "reply": "怎么了？", "replyPinyin": "zěn me le？", "vocabList": [{"word":"生气","pinyin":"shēngqì","translation":"angry","hskLevel":2}] },
        { "id": "mood_05", "title": "05. 我有点担心 | I'm a little worried", "isFree": true, "audioKey": "230", "sentence": "我有点担心。", "pinyin": "Wǒ yǒudiǎn dānxīn.", "translation": "I'm a little worried.", "note": "“担心” = worry. “有点” makes it softer. Very common when waiting for news or results.", "reply": "别担心，没事的。", "replyPinyin": "bié dān xīn， méi shì de。", "vocabList": [{"word":"担心","pinyin":"dānxīn","translation":"to worry","hskLevel":2}] },
        { "id": "mood_06", "title": "06. 我很着急 | I'm anxious", "isFree": false, "audioKey": "231", "sentence": "我很着急。", "pinyin": "Wǒ hěn zháojí.", "translation": "I'm very anxious / in a hurry.", "note": "“着急” can mean anxious or rushed. It's used when you're worried about time or a situation.", "reply": "别急，慢慢来。", "replyPinyin": "bié jí， màn màn lái。", "vocabList": [{"word":"着急","pinyin":"zháojí","translation":"anxious","hskLevel":2}] },
        { "id": "mood_07", "title": "07. 我害怕 | I'm scared", "isFree": false, "audioKey": "232", "sentence": "我害怕。", "pinyin": "Wǒ hàipà.", "translation": "I'm scared.", "note": "“害怕” = afraid/scared. Use it for real fear, like heights, dogs, or a scary movie.", "reply": "别怕，我在。", "replyPinyin": "bié pà， wǒ zài。", "vocabList": [{"word":"害怕","pinyin":"hàipà","translation":"afraid","hskLevel":2}] },
        { "id": "mood_08", "title": "08. 我很难过 | I'm very sad", "isFree": false, "audioKey": "233", "sentence": "我很难过。", "pinyin": "Wǒ hěn nánguò.", "translation": "I'm very sad.", "note": "“难过” = sad. It literally means “hard to pass,” like a feeling that's hard to get through.", "reply": "抱抱。", "replyPinyin": "bào bào。", "vocabList": [{"word":"难过","pinyin":"nánguò","translation":"sad","hskLevel":2}] },
        { "id": "mood_09", "title": "09. 别难过 | Don't be sad", "isFree": false, "audioKey": "234", "sentence": "别难过。", "pinyin": "Bié nánguò.", "translation": "Don't be sad.", "note": "“别” + verb = don't do something. “别难过” is a warm, simple way to comfort someone.", "reply": "谢谢你。", "replyPinyin": "xiè xiè nǐ。", "vocabList": [{"word":"别","pinyin":"bié","translation":"don't","hskLevel":1}] },
        { "id": "mood_10", "title": "10. 没关系，别担心 | It's okay, don't worry", "isFree": false, "audioKey": "235", "sentence": "没关系，别担心。", "pinyin": "Méi guānxi, bié dānxīn.", "translation": "It's okay, don't worry.", "note": "Two comfort phrases together. “没关系” = it's okay. “别担心” = don't worry. Very reassuring.", "reply": "好，谢谢。", "replyPinyin": "hǎo， xiè xiè。", "vocabList": [{"word":"没关系","pinyin":"méi guānxi","translation":"it's okay","hskLevel":1}] },
        { "id": "mood_11", "title": "11. 太好了 | That's great", "isFree": false, "audioKey": "236", "sentence": "太好了！", "pinyin": "Tài hǎo le!", "translation": "That's great!", "note": "Literally “too good.” It's an exclamation of happiness or excitement. Use it when you hear good news.", "reply": "是啊！", "replyPinyin": "shì a！", "vocabList": [{"word":"太……了","pinyin":"tài...le","translation":"too / very","hskLevel":2}] },
        { "id": "mood_12", "title": "12. 真的吗 | Really", "isFree": false, "audioKey": "237", "sentence": "真的吗？", "pinyin": "Zhēn de ma?", "translation": "Really?", "note": "“真的” = real/true. “吗” makes it a question. Use it to show surprise or ask for confirmation.", "reply": "真的。", "replyPinyin": "zhēn de。", "vocabList": [{"word":"真的","pinyin":"zhēn de","translation":"really","hskLevel":1}] },
        { "id": "mood_13", "title": "13. 我也是 | Me too", "isFree": false, "audioKey": "238", "sentence": "我也是。", "pinyin": "Wǒ yě shì.", "translation": "Me too.", "note": "“也” = also. “是” = am/is/are. This is the simplest way to agree or share the same feeling.", "reply": "太好了，我们一样。", "replyPinyin": "tài hǎo le， wǒ men yī yàng。", "vocabList": [{"word":"也","pinyin":"yě","translation":"also","hskLevel":1}] },
        { "id": "mood_14", "title": "14. 我同意 | I agree", "isFree": false, "audioKey": "239", "sentence": "我同意。", "pinyin": "Wǒ tóngyì.", "translation": "I agree.", "note": "“同意” = agree. Use it in discussions, meetings, or when someone makes a suggestion.", "reply": "谢谢你的支持。", "replyPinyin": "xiè xiè nǐ de zhī chí。", "vocabList": [{"word":"同意","pinyin":"tóngyì","translation":"to agree","hskLevel":2}] },
        { "id": "mood_15", "title": "15. 我不同意 | I disagree", "isFree": false, "audioKey": "240", "sentence": "我不同意。", "pinyin": "Wǒ bù tóngyì.", "translation": "I disagree.", "note": "“不同意” = disagree. It's direct but not rude. You can soften it by saying “我有点不同意” (I kind of disagree).", "reply": "为什么？", "replyPinyin": "wèi shén me？", "vocabList": [{"word":"同意","pinyin":"tóngyì","translation":"to agree","hskLevel":2}] }
      ]
