        { "id": "stay_02", "title": "02. 你家在哪里 | Where is your home", "isFree": true, "audioKey": "242", "sentence": "你家在哪里？", "pinyin": "Nǐ jiā zài nǎlǐ?", "translation": "Where is your home?", "note": "“家” = home/family. “在哪里” = where. This is a simple way to ask where someone lives.", "reply": "我家在学校旁边。", "replyPinyin": "wǒ jiā zài xué xiào páng biān。", "vocabList": [{"word":"家","pinyin":"jiā","translation":"home","hskLevel":1}] },
        { "id": "stay_03", "title": "03. 我坐飞机去 | I'll go by plane", "isFree": true, "audioKey": "243", "sentence": "我坐飞机去。", "pinyin": "Wǒ zuò fēijī qù.", "translation": "I'll go by plane.", "note": "“坐” = sit/take (transportation). “飞机” = airplane. Pattern: 坐 + vehicle + 去.", "reply": "几点的飞机？", "replyPinyin": "jǐ diǎn de fēi jī？", "vocabList": [{"word":"飞机","pinyin":"fēijī","translation":"airplane","hskLevel":2}] },
        { "id": "stay_04", "title": "04. 我坐火车去 | I'll go by train", "isFree": true, "audioKey": "244", "sentence": "我坐火车去。", "pinyin": "Wǒ zuò huǒchē qù.", "translation": "I'll go by train.", "note": "“火车” = train. In China, trains are a major way to travel between cities.", "reply": "火车很快。", "replyPinyin": "huǒ chē hěn kuài。", "vocabList": [{"word":"火车","pinyin":"huǒchē","translation":"train","hskLevel":2}] },
        { "id": "stay_05", "title": "05. 我坐出租车去 | I'll go by taxi", "isFree": true, "audioKey": "245", "sentence": "我坐出租车去。", "pinyin": "Wǒ zuò chūzūchē qù.", "translation": "I'll go by taxi.", "note": "“出租车” = taxi. In Singapore, people often say “taxi” directly, but “出租车” is understood.", "reply": "好，路上小心。", "replyPinyin": "hǎo， lù shàng xiǎo xīn。", "vocabList": [{"word":"出租车","pinyin":"chūzūchē","translation":"taxi","hskLevel":2}] },
        { "id": "stay_06", "title": "06. 我坐地铁去 | I'll go by subway", "isFree": false, "audioKey": "246", "sentence": "我坐地铁去。", "pinyin": "Wǒ zuò dìtiě qù.", "translation": "I'll go by subway.", "note": "“地铁” = subway/metro. In Singapore it's called MRT, but “地铁” is still understood by Chinese speakers.", "reply": "地铁很方便。", "replyPinyin": "dì tiě hěn fāng biàn。", "vocabList": [{"word":"地铁","pinyin":"dìtiě","translation":"subway","hskLevel":2}] },
        { "id": "stay_07", "title": "07. 我要买票 | I want to buy a ticket", "isFree": false, "audioKey": "247", "sentence": "我要买票。", "pinyin": "Wǒ yào mǎi piào.", "translation": "I want to buy a ticket.", "note": "“买票” = buy a ticket. Use it for trains, buses, movies, or attractions.", "reply": "去哪里？", "replyPinyin": "qù nǎ lǐ？", "vocabList": [{"word":"买票","pinyin":"mǎi piào","translation":"buy a ticket","hskLevel":2}] },
        { "id": "stay_08", "title": "08. 一张票多少钱 | How much is one ticket", "isFree": false, "audioKey": "248", "sentence": "一张票多少钱？", "pinyin": "Yì zhāng piào duōshao qián?", "translation": "How much is one ticket?", "note": "“张” is the measure word for tickets. “多少钱” = how much money.", "reply": "五十块。", "replyPinyin": "wǔ shí kuài。", "vocabList": [{"word":"票","pinyin":"piào","translation":"ticket","hskLevel":2}] },
        { "id": "stay_09", "title": "09. 火车站在哪里 | Where is the train station", "isFree": false, "audioKey": "249", "sentence": "火车站在哪里？", "pinyin": "Huǒchēzhàn zài nǎlǐ?", "translation": "Where is the train station?", "note": "“火车站” = train station. “在哪里” = where. Very useful for travelers.", "reply": "在前面。", "replyPinyin": "zài qián miàn。", "vocabList": [{"word":"火车站","pinyin":"huǒchēzhàn","translation":"train station","hskLevel":2}] },
        { "id": "stay_10", "title": "10. 机场远吗 | Is the airport far", "isFree": false, "audioKey": "250", "sentence": "机场远吗？", "pinyin": "Jīchǎng yuǎn ma?", "translation": "Is the airport far?", "note": "“机场” = airport. “远” = far. Use this when you need to know travel time.", "reply": "有点远，坐车要一个小时。", "replyPinyin": "yǒu diǎn yuǎn， zuò chē yào yī gè xiǎo shí。", "vocabList": [{"word":"机场","pinyin":"jīchǎng","translation":"airport","hskLevel":2}] },
        { "id": "stay_11", "title": "11. 我明天出发 | I depart tomorrow", "isFree": false, "audioKey": "251", "sentence": "我明天出发。", "pinyin": "Wǒ míngtiān chūfā.", "translation": "I depart tomorrow.", "note": "“出发” = set off/depart. Use it for trips, flights, or long journeys.", "reply": "几点出发？", "replyPinyin": "jǐ diǎn chū fā？", "vocabList": [{"word":"出发","pinyin":"chūfā","translation":"to depart","hskLevel":2}] },
        { "id": "stay_12", "title": "12. 我住在宾馆 | I'm staying at a hotel", "isFree": false, "audioKey": "252", "sentence": "我住在宾馆。", "pinyin": "Wǒ zhù zài bīnguǎn.", "translation": "I'm staying at a hotel.", "note": "“宾馆” = hotel/guesthouse. In mainland China, “宾馆” and “酒店” are both used. “酒店” is HSK4, so “宾馆” is the HSK3 choice.", "reply": "宾馆怎么样？", "replyPinyin": "bīn guǎn zěn me yàng？", "vocabList": [{"word":"宾馆","pinyin":"bīnguǎn","translation":"hotel","hskLevel":3}] },
        { "id": "stay_13", "title": "13. 房间很干净 | The room is very clean", "isFree": false, "audioKey": "253", "sentence": "房间很干净。", "pinyin": "Fángjiān hěn gānjìng.", "translation": "The room is very clean.", "note": "“房间” = room. “干净” = clean. A simple compliment about accommodation.", "reply": "那就好。", "replyPinyin": "nà jiù hǎo。", "vocabList": [{"word":"干净","pinyin":"gānjìng","translation":"clean","hskLevel":2}] },
        { "id": "stay_14", "title": "14. 我想回家 | I want to go home", "isFree": false, "audioKey": "254", "sentence": "我想回家。", "pinyin": "Wǒ xiǎng huí jiā.", "translation": "I want to go home.", "note": "“回” = return. “家” = home. This is a very natural sentence when you're tired or homesick.", "reply": "我也是。", "replyPinyin": "wǒ yě shì。", "vocabList": [{"word":"回家","pinyin":"huí jiā","translation":"go home","hskLevel":1}] },
        { "id": "stay_15", "title": "15. 路上小心 | Take care on the way", "isFree": false, "audioKey": "255", "sentence": "路上小心。", "pinyin": "Lùshang xiǎoxīn.", "translation": "Take care on the way.", "note": "“路上” = on the road/way. “小心” = be careful. This is a warm, common farewell phrase when someone is traveling.", "reply": "好，谢谢。", "replyPinyin": "hǎo， xiè xiè。", "vocabList": [{"word":"小心","pinyin":"xiǎoxīn","translation":"be careful","hskLevel":2}] }
