      "intro": "Say happy birthday, happy new year, and warm wishes — celebrate any occasion in Chinese.",
      "introZh": "生日、新年、春节的祝福语，以及收礼送礼的礼貌表达。",
      "cards": [
        { "id": "fest_01", "title": "01. 生日快乐 | Happy birthday", "isFree": true, "audioKey": "256", "sentence": "生日快乐！", "pinyin": "Shēngrì kuàilè!", "translation": "Happy birthday!", "note": "“生日” = birthday. “快乐” = happy. This is the standard birthday greeting. You can also say “祝你生日快乐” for “Wish you a happy birthday.”", "reply": "谢谢！", "replyPinyin": "xiè xiè！", "vocabList": [{"word":"生日","pinyin":"shēngrì","translation":"birthday","hskLevel":1}] },
        { "id": "fest_02", "title": "02. 新年快乐 | Happy New Year", "isFree": true, "audioKey": "257", "sentence": "新年快乐！", "pinyin": "Xīnnián kuàilè!", "translation": "Happy New Year!", "note": "“新年” = New Year. Use this for January 1st or Chinese New Year. It's the most common holiday greeting.", "reply": "新年快乐！", "replyPinyin": "xīn nián kuài lè！", "vocabList": [{"word":"新年","pinyin":"xīnnián","translation":"New Year","hskLevel":2}] },
        { "id": "fest_03", "title": "03. 春节快乐 | Happy Spring Festival", "isFree": true, "audioKey": "258", "sentence": "春节快乐！", "pinyin": "Chūnjié kuàilè!", "translation": "Happy Spring Festival!", "note": "“春节” = Spring Festival / Chinese New Year. This is the biggest holiday in China and among Chinese communities worldwide.", "reply": "春节快乐！", "replyPinyin": "chūn jié kuài lè！", "vocabList": [{"word":"春节","pinyin":"chūnjié","translation":"Spring Festival","hskLevel":2}] },
        { "id": "fest_04", "title": "04. 节日快乐 | Happy holiday", "isFree": true, "audioKey": "259", "sentence": "节日快乐！", "pinyin": "Jiérì kuàilè!", "translation": "Happy holiday!", "note": "“节日” = holiday/festival. This is a general greeting for any holiday. Safe and polite.", "reply": "谢谢，你也快乐。", "replyPinyin": "xiè xiè， nǐ yě kuài lè。", "vocabList": [{"word":"节日","pinyin":"jiérì","translation":"festival","hskLevel":2}] },
        { "id": "fest_05", "title": "05. 祝你健康 | Wish you good health", "isFree": true, "audioKey": "260", "sentence": "祝你健康！", "pinyin": "Zhù nǐ jiànkāng!", "translation": "Wish you good health!", "note": "“祝” = wish. “健康” = health. This is a very common and warm blessing, especially for older people.", "reply": "谢谢，也祝你健康。", "replyPinyin": "xiè xiè， yě zhù nǐ jiàn kāng。", "vocabList": [{"word":"健康","pinyin":"jiànkāng","translation":"health","hskLevel":2}] },
        { "id": "fest_06", "title": "06. 祝你顺利 | Wish you success", "isFree": false, "audioKey": "261", "sentence": "祝你顺利！", "pinyin": "Zhù nǐ shùnlì!", "translation": "Wish you success / smooth progress!", "note": "“顺利” = smooth/successful. Use it for exams, interviews, travel, or new jobs. Very encouraging.", "reply": "谢谢，我会努力。", "replyPinyin": "xiè xiè， wǒ huì nǔ lì。", "vocabList": [{"word":"顺利","pinyin":"shùnlì","translation":"smooth","hskLevel":3}] },
        { "id": "fest_07", "title": "07. 恭喜你 | Congratulations", "isFree": false, "audioKey": "262", "sentence": "恭喜你！", "pinyin": "Gōngxǐ nǐ!", "translation": "Congratulations!", "note": "“恭喜” = congratulate. Use it for good news like a new job, graduation, or marriage.", "reply": "谢谢！", "replyPinyin": "xiè xiè！", "vocabList": [{"word":"恭喜","pinyin":"gōngxǐ","translation":"congratulate","hskLevel":2}] },
        { "id": "fest_08", "title": "08. 这是给你的礼物 | A gift for you", "isFree": false, "audioKey": "263", "sentence": "这是给你的礼物。", "pinyin": "Zhè shì gěi nǐ de lǐwù.", "translation": "This is a gift for you.", "note": "“礼物” = gift. “给” = for/to. When giving a gift, use both hands in Chinese culture to show respect.", "reply": "太客气了，谢谢！", "replyPinyin": "tài kè qì le， xiè xiè！", "vocabList": [{"word":"礼物","pinyin":"lǐwù","translation":"gift","hskLevel":2}] },
        { "id": "fest_09", "title": "09. 我很喜欢这个礼物 | I like this gift", "isFree": false, "audioKey": "264", "sentence": "我很喜欢这个礼物。", "pinyin": "Wǒ hěn xǐhuan zhège lǐwù.", "translation": "I really like this gift.", "note": "“喜欢” = like. This is a warm way to thank someone for a gift.", "reply": "你喜欢就好。", "replyPinyin": "nǐ xǐ huān jiù hǎo。", "vocabList": [{"word":"喜欢","pinyin":"xǐhuan","translation":"to like","hskLevel":1}] },
        { "id": "fest_10", "title": "10. 谢谢你的礼物 | Thanks for your gift", "isFree": false, "audioKey": "265", "sentence": "谢谢你的礼物。", "pinyin": "Xièxie nǐ de lǐwù.", "translation": "Thank you for your gift.", "note": "Simple and polite. You can add “我很喜欢” to make it warmer.", "reply": "不客气。", "replyPinyin": "bù kè qì。", "vocabList": [{"word":"礼物","pinyin":"lǐwù","translation":"gift","hskLevel":2}] },
        { "id": "fest_11", "title": "11. 我们一起吃饭吧 | Let's eat together", "isFree": false, "audioKey": "266", "sentence": "我们一起吃饭吧。", "pinyin": "Wǒmen yìqǐ chīfàn ba.", "translation": "Let's eat together.", "note": "“一起” = together. “吧” = suggestion. Food is central to Chinese celebrations. This is a friendly invitation.", "reply": "好啊！", "replyPinyin": "hǎo a！", "vocabList": [{"word":"一起","pinyin":"yìqǐ","translation":"together","hskLevel":1}] },
        { "id": "fest_12", "title": "12. 今天是我的生日 | Today is my birthday", "isFree": false, "audioKey": "267", "sentence": "今天是我的生日。", "pinyin": "Jīntiān shì wǒ de shēngrì.", "translation": "Today is my birthday.", "note": "“今天” = today. Use this to let people know so they can wish you happy birthday.", "reply": "生日快乐！", "replyPinyin": "shēng rì kuài lè！", "vocabList": [{"word":"生日","pinyin":"shēngrì","translation":"birthday","hskLevel":1}] },
        { "id": "fest_13", "title": "13. 你什么时候生日 | When is your birthday", "isFree": false, "audioKey": "268", "sentence": "你什么时候生日？", "pinyin": "Nǐ shénme shíhou shēngrì?", "translation": "When is your birthday?", "note": "“什么时候” = when. This is a common question among friends.", "reply": "下个月。", "replyPinyin": "xià gè yuè。", "vocabList": [{"word":"什么时候","pinyin":"shénme shíhou","translation":"when","hskLevel":1}] },
        { "id": "fest_14", "title": "14. 我请你吃饭 | I'll treat you to a meal", "isFree": false, "audioKey": "269", "sentence": "我请你吃饭。", "pinyin": "Wǒ qǐng nǐ chīfàn.", "translation": "I'll treat you to a meal.", "note": "“请” = invite/treat. In Chinese culture, treating someone to a meal is a common way to show friendship or gratitude.", "reply": "那我就不客气了。", "replyPinyin": "nà wǒ jiù bù kè qì le。", "vocabList": [{"word":"请客","pinyin":"qǐngkè","translation":"to treat (to a meal)","hskLevel":2}] },
        { "id": "fest_15", "title": "15. 祝你玩得开心 | Have fun", "isFree": false, "audioKey": "270", "sentence": "祝你玩得开心。", "pinyin": "Zhù nǐ wán de kāixīn.", "translation": "Wish you a happy time / Have fun.", "note": "“玩得开心” = play happily / have fun. Use it when someone is going on a trip, to a party, or doing something fun.", "reply": "谢谢，我会的。", "replyPinyin": "xiè xiè， wǒ huì de。", "vocabList": [{"word":"开心","pinyin":"kāixīn","translation":"happy","hskLevel":2}] }
      ]
